Class Alcancia
  Define juntado As Integer;

  Method Constructor()
    This.juntado <- 0;
  EndMethod

  Method Depositar(monedas As Integer)
    This.juntado <- This.juntado + monedas;
  EndMethod

  Method Total() As Integer
    Return This.juntado;
  EndMethod
EndClass

Algorithm Ahorro
  Define alcancia As Alcancia <- New Alcancia();
  Define monedas As Integer;
  Read monedas;
  While monedas <> 0 Do
    alcancia.Depositar(monedas);
    Read monedas;
  EndWhile
  Write alcancia.Total();
EndAlgorithm
